/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.updateDeployProcDefault */  
UPDATE 
    KOA_TB_DEPLOY_PROC    
SET
    DEPLOY_CD = #{deployCd}

        ,VERIFI_CD = #{verifiCd}


        ,bigo = #{bigo}


        ,USE_YN = #{useYn}

    ,UPDATE_USR      = #{regr}
    ,DEPLOY_ADM      = #{deployAdm}
    ,UPDATE_DT       = NOW()
WHERE
    (KOA_TB_DEPLOY_PROC.SEQ = #{seq})

 /* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.updateDeployApplyDefault */  
UPDATE 
    KOA_TB_DEPLOY_APPLY
SET DEPLOY_CD = #{deployCd}
   ,DEPLOY_DESC = #{deployDesc}
   ,DEPLOY_ADM = #{deployAdm}
   ,BIGO = #{bigo}
   ,COMMENT = #{comment}
WHERE 
    SEQ = #{seq}

/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.updateDeployApplyReject */  
UPDATE KOA_TB_DEPLOY_APPLY
SET DEPLOY_CD = #{deployCd}
   ,DEPLOY_ADM = #{deployAdm}
   ,COMMENT = #{comment}
WHERE
    SEQ = #{seq}

