/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.selDeployList */
SELECT ROW_NUMBER() OVER (ORDER BY DEPLOY_PROC.REG_DT DESC) rownum, DEPLOY_PROC.SEQ SEQ, DEPLOY_COMNCD.CD_NM DEPLOY_CDNM, VERIFI_COMNCD.CD_NM VERIFI_CDNM, DEPLOY_COMNCD.PRNTS_CD PRNTS_CD, APISYSTEM.SYS_NM, SPC.API_NM CTGRY_NM, DEF.API_NM, DEPLOY_PROC.DEPLOY_CD, DEPLOY_PROC.VERIFI_CD, DEPLOY_PROC.regr, TO_CHAR(DEPLOY_PROC.REG_DT, 'Mon DD YYYY') REG_DT, COALESCE(DEPLOY_PROC.BIGO,'') BIGO, COALESCE(DEF.API_VER,'') API_VER FROM KOA_TB_COMN_CD AS DEPLOY_COMNCD INNER JOIN KOA_TB_DEPLOY_PROC AS DEPLOY_PROC ON DEPLOY_COMNCD.COMN_CD = DEPLOY_PROC.DEPLOY_CD INNER JOIN KOA_TB_API_DEF AS DEF ON DEPLOY_PROC.API_NO = DEF.API_NO INNER JOIN KOA_TB_API_SPC AS SPC ON DEF.API_SPC_NO = SPC.API_SPC_NO INNER JOIN KOA_TB_API_SYSTEM AS APISYSTEM ON SPC.SYS_ID = APISYSTEM.SYS_ID INNER JOIN KOA_TB_COMN_CD AS VERIFI_COMNCD ON DEPLOY_PROC.VERIFI_CD = VERIFI_COMNCD.COMN_CD WHERE (1=1)
AND DEPLOY_PROC.VERIFI_CD = #{searchVerifi}
AND DEPLOY_PROC.DEPLOY_CD = #{searchDeploy}
AND APISYSTEM.SYS_ID = #{searchSystem}
AND SPC.API_SPC_NO = #{searchSpc}
AND DEPLOY_PROC.REG_DT >= #{stDate}
AND DEPLOY_PROC.REG_DT < #{endDate}
AND UPPER(DEF.API_NM) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%')
AND SEQ = #{seq}
AND APISYSTEM.SYS_ID IN
#{item}
AND (1!=1)

