 SELECT
     COUNT(*) AS cnt
 FROM 
     KOA_TB_COMN_CD AS DEPLOY_COMNCD 
     INNER JOIN KOA_TB_DEPLOY_PROC AS DEPLOY_PROC  ON DEPLOY_COMNCD.COMN_CD = DEPLOY_PROC.DEPLOY_CD
     INNER JOIN KOA_TB_API_DEF AS DEF  ON DEPLOY_PROC.API_NO = DEF.API_NO
     INNER JOIN KOA_TB_API_SPC AS SPC  ON DEF.API_SPC_NO = SPC.API_SPC_NO
     INNER JOIN KOA_TB_API_SYSTEM AS APISYSTEM  ON SPC.SYS_ID = APISYSTEM.SYS_ID
     INNER JOIN KOA_TB_COMN_CD AS VERIFI_COMNCD  ON DEPLOY_PROC.VERIFI_CD = VERIFI_COMNCD.COMN_CD
WHERE (1=1)

     AND DEPLOY_PROC.VERIFI_CD = #{searchVerifi}


     AND DEPLOY_PROC.DEPLOY_CD = #{searchDeploy}


     AND APISYSTEM.SYS_ID = #{searchSystem}


     AND SPC.API_SPC_NO = #{searchSpc}


     AND DEPLOY_PROC.REG_DT >= #{stDate}


     AND DEPLOY_PROC.REG_DT < #{endDate}


      AND UPPER(DEF.API_NM) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%')


     AND SEQ = #{seq}




         AND APISYSTEM.SYS_ID IN

             #{item}



         AND (1!=1)

/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.selDeployApplyList */
SELECT ROW_NUMBER() OVER (ORDER BY DEPLOY_PROC.REG_DT DESC) rownum, DEPLOY_PROC.SEQ SEQ, DEPLOY_COMNCD.CD_NM DEPLOY_CDNM, VERIFI_COMNCD.CD_NM VERIFI_CDNM, DEPLOY_COMNCD.PRNTS_CD PRNTS_CD, APISYSTEM.SYS_NM, SPC.API_NM CTGRY_NM, DEF.API_NM, DEPLOY_PROC.DEPLOY_CD, DEPLOY_PROC.VERIFI_CD, DEPLOY_PROC.regr, TO_CHAR(DEPLOY_PROC.REG_DT, 'Mon DD YYYY') REG_DT, COALESCE(DEPLOY_PROC.BIGO,'') BIGO, DEPLOYAPPLY.SEQ DEPLOY_APPLY_SEQ, DEF.API_NO , DEF.API_ID , COALESCE(DEF.API_VER,'') API_VER FROM KOA_TB_COMN_CD AS DEPLOY_COMNCD INNER JOIN KOA_TB_DEPLOY_PROC AS DEPLOY_PROC ON DEPLOY_COMNCD.COMN_CD = DEPLOY_PROC.DEPLOY_CD INNER JOIN KOA_TB_API_DEF AS DEF ON DEPLOY_PROC.API_NO = DEF.API_NO INNER JOIN KOA_TB_API_SPC AS SPC ON DEF.API_SPC_NO = SPC.API_SPC_NO INNER JOIN KOA_TB_API_SYSTEM AS APISYSTEM ON SPC.SYS_ID = APISYSTEM.SYS_ID INNER JOIN KOA_TB_COMN_CD AS VERIFI_COMNCD ON DEPLOY_PROC.VERIFI_CD = VERIFI_COMNCD.COMN_CD INNER JOIN KOA_TB_DEPLOY_APPLY AS DEPLOYAPPLY ON DEPLOYAPPLY.DEPLOY_PROC_SEQ = DEPLOY_PROC.SEQ WHERE DEPLOY_PROC.DEPLOY_CD = 'DEPLOY1050' AND DEPLOYAPPLY.DEPLOY_CD = 'DEPLOY1050'
AND DEPLOY_PROC.VERIFI_CD = #{searchVerifi}
AND DEPLOY_PROC.DEPLOY_CD = #{searchDeploy}
AND DEPLOYAPPLY.DEPLOY_CD = #{searchApplyCd}
AND APISYSTEM.SYS_ID = #{searchSystem}
AND DEPLOY_PROC.REG_DT >= #{stDate}
AND DEPLOY_PROC.REG_DT < #{endDate}
AND UPPER(DEF.API_NM) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%')
AND SEQ = #{seq}

 /* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.selDeployApplyListCnt */ 
SELECT
  COUNT(*) AS cnt
FROM 
    KOA_TB_COMN_CD AS DEPLOY_COMNCD 
    INNER JOIN KOA_TB_DEPLOY_PROC AS DEPLOY_PROC  ON DEPLOY_COMNCD.COMN_CD = DEPLOY_PROC.DEPLOY_CD
    INNER JOIN KOA_TB_API_DEF AS DEF  ON DEPLOY_PROC.API_NO = DEF.API_NO
    INNER JOIN KOA_TB_API_SPC AS SPC  ON DEF.API_SPC_NO = SPC.API_SPC_NO
    INNER JOIN KOA_TB_API_SYSTEM AS APISYSTEM  ON SPC.SYS_ID = APISYSTEM.SYS_ID
    INNER JOIN KOA_TB_COMN_CD AS VERIFI_COMNCD  ON DEPLOY_PROC.VERIFI_CD = VERIFI_COMNCD.COMN_CD
    INNER JOIN KOA_TB_DEPLOY_APPLY AS DEPLOYAPPLY  ON DEPLOYAPPLY.DEPLOY_PROC_SEQ = DEPLOY_PROC.SEQ
WHERE DEPLOY_PROC.DEPLOY_CD = 'DEPLOY1050' AND DEPLOYAPPLY.DEPLOY_CD = 'DEPLOY1050' 

        AND DEPLOY_PROC.VERIFI_CD = #{searchVerifi}


        AND DEPLOY_PROC.DEPLOY_CD = #{searchDeploy}


        AND APISYSTEM.SYS_ID = #{searchSystem}


        AND DEPLOY_PROC.REG_DT >= #{stDate}


        AND DEPLOY_PROC.REG_DT < #{endDate}


         AND UPPER(DEF.API_NM) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%') 


        AND SEQ = #{seq}

/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.selVerifiResult */
SELECT A.SEQ , TO_CHAR(A.VERIFICATION_DT, 'YYYY-MM-DD HH24:MI:SS') VERIFICATION_DT , A.RESULT_CD , A.RESULT_MSG , A.SUCCESS_YN FROM KOA_TB_API_VERI_CONDITION AS A WHERE (A.API_NO = #{apiNo}) ORDER BY A.VERIFICATION_DT DESC
SELECT A.SEQ, TO_CHAR(A.VERIFICATION_DT, 'YYYY-MM-DD HH24:MI:SS.MS') VERIFICATION_DT, A.RESULT_CD, A.RESULT_MSG, A.SUCCESS_YN FROM KOA_TB_API_VERI_CONDITION AS A INNER JOIN KOA_TB_DEPLOY_PROC AS B ON A.DEPLOY_PROC_SEQ = B.SEQ WHERE (B.SEQ = #{deployProcSeq}) ORDER BY A.VERIFICATION_DT DESC

/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.selDeployHstList */
SELECT ROW_NUMBER() OVER (ORDER BY DEPLOY_HST.DEPLOY_DATE DESC) rownum, DEPLOY_HST.SEQ, APISYSTEM.SYS_NM , SPC.API_NM SERVICE_NM, DEF.API_NM, TO_CHAR(DEPLOY_HST.DEPLOY_DATE, 'Mon DD YYYY') DEPLOY_DATE, TO_CHAR(DEPLOY_APPLY.REG_DT, 'Mon DD YYYY') REG_DT, DEPLOY_HST.SUCCESS_YN, DEPLOY_APPLY.SEQ DEPLOY_APPLY_SEQ, DEPLOY_PROC.SEQ depSeq FROM (SELECT MAX(DEPLOY_DATE) DEPLOY_DATE , MAX(SEQ) SEQ ,(SELECT SUCCESS_YN FROM KOA_TB_DEPLOY_HST WHERE SEQ=MAX(AA.SEQ)) SUCCESS_YN , DEPLOY_APPLY_SEQ FROM KOA_TB_DEPLOY_HST AA GROUP BY DEPLOY_APPLY_SEQ) AS DEPLOY_HST INNER JOIN KOA_TB_DEPLOY_APPLY AS DEPLOY_APPLY ON DEPLOY_HST.DEPLOY_APPLY_SEQ = DEPLOY_APPLY.SEQ INNER JOIN KOA_TB_DEPLOY_PROC AS DEPLOY_PROC ON DEPLOY_APPLY.DEPLOY_PROC_SEQ = DEPLOY_PROC.SEQ INNER JOIN KOA_TB_API_DEF AS DEF ON DEPLOY_PROC.API_NO = DEF.API_NO INNER JOIN KOA_TB_API_SPC AS SPC ON DEF.API_SPC_NO = SPC.API_SPC_NO INNER JOIN KOA_TB_API_SYSTEM AS APISYSTEM ON SPC.SYS_ID = APISYSTEM.SYS_ID WHERE DEPLOY_PROC.DEPLOY_CD IN ('DEPLOY1063','DEPLOY1065','DEPLOY1070')
AND APISYSTEM.SYS_ID = #{searchSystem}
AND DEPLOY_HST.DEPLOY_DATE >= #{stDate}
AND DEPLOY_HST.DEPLOY_DATE < #{endDate}

/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.selDeployHstCnt */ SELECT COUNT(*) AS cnt FROM (SELECT MAX(DEPLOY_DATE) DEPLOY_DATE , MAX(SEQ) SEQ ,(SELECT SUCCESS_YN FROM KOA_TB_DEPLOY_HST WHERE SEQ=MAX(AA.SEQ)) SUCCESS_YN , DEPLOY_APPLY_SEQ FROM KOA_TB_DEPLOY_HST AA GROUP BY DEPLOY_APPLY_SEQ) AS DEPLOY_HST INNER JOIN KOA_TB_DEPLOY_APPLY AS DEPLOY_APPLY ON DEPLOY_HST.DEPLOY_APPLY_SEQ = DEPLOY_APPLY.SEQ INNER JOIN KOA_TB_DEPLOY_PROC AS DEPLOY_PROC ON DEPLOY_APPLY.DEPLOY_PROC_SEQ = DEPLOY_PROC.SEQ INNER JOIN KOA_TB_API_DEF AS DEF ON DEPLOY_PROC.API_NO = DEF.API_NO INNER JOIN KOA_TB_API_SPC AS SPC ON DEF.API_SPC_NO = SPC.API_SPC_NO INNER JOIN KOA_TB_API_SYSTEM AS APISYSTEM ON SPC.SYS_ID = APISYSTEM.SYS_ID WHERE DEPLOY_PROC.DEPLOY_CD IN ('DEPLOY1065','DEPLOY1070')
AND APISYSTEM.SYS_ID = #{searchSystem}
AND DEPLOY_HST.DEPLOY_DATE >= #{stDate}
AND DEPLOY_HST.DEPLOY_DATE < #{endDate}

mapper.insert:
  /* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.insertDeployHst */    
  INSERT INTO KOA_TB_DEPLOY_HST
(
  DEPLOY_DATE
 ,DEPLOY_APPLY_SEQ 
 ,DEPLOY_PROC_SEQ 
 ,DEPLOY_ADM
 ,API_NO
 ,LOG_SEQ
 ,SUCCESS_YN
 ,RESULT_MSG
 ,RESULT_CD
 ,DEPLOY_GB
)
VALUES
(
  NOW()
  ,#{deployApplySeq}
  ,#{deployProcSeq}
  ,#{deployAdm}
  ,#{apiNo}
  ,#{logSeq}
  ,#{successYn}
  ,#{resultMsg}
  ,#{resultCd}
  ,#{deployGb}
)

/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.insertVerifiDefault */    
