mapper.select:
/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.selTescCaseList */ SELECT ROW_NUMBER() OVER (ORDER BY TEST_CASE_LIST.SEQ DESC) rownum, TEST_CASE_LIST.API_NO, TEST_CASE_LIST.CASE_NM, COMN_CD.CD_NM, COALESCE(B.CNT,0) AS VERIFI_SUCCESS, COALESCE(C.CNT,0) AS VERIFI_FAIL, COALESCE((SELECT SUCCESS_YN FROM KOA_TB_API_VERI_CONDITION WHERE TEST_CASE_SEQ = TEST_CASE_LIST.SEQ ORDER BY SEQ DESC LIMIT 1),'X') AS LAST_SUCCESS_YN, TEST_CASE_LIST.SEQ TEST_CASE_SEQ FROM KOA_TB_TEST_CASE_LIST AS TEST_CASE_LIST INNER JOIN KOA_TB_COMN_CD AS COMN_CD ON TEST_CASE_LIST.CASE_CODE = COMN_CD.COMN_CD LEFT OUTER JOIN ( SELECT COUNT(*) AS CNT , VC.TEST_CASE_SEQ FROM KOA_TB_API_VERI_CONDITION AS VC WHERE VC.SUCCESS_YN = 'Y' GROUP BY VC.TEST_CASE_SEQ ) B ON (B.TEST_CASE_SEQ = TEST_CASE_LIST.SEQ) LEFT OUTER JOIN ( SELECT COUNT(*) AS CNT , VC.TEST_CASE_SEQ FROM KOA_TB_API_VERI_CONDITION AS VC WHERE VC.SUCCESS_YN = 'F' GROUP BY VC.TEST_CASE_SEQ ) C ON (C.TEST_CASE_SEQ = TEST_CASE_LIST.SEQ) WHERE TEST_CASE_LIST.DEL_YN = 'N'
AND TEST_CASE_LIST.CASE_CODE = #{caseCd}
AND TEST_CASE_LIST.API_NO = #{apiNo}

/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.selEmailSendList */    
SELECT 
    AUTMPPG.MBR_ID, TBMBR.EMAIL 
FROM 
    KOA_TB_AUT TBAUT 
        INNER JOIN KOA_TB_AUT_MPPG AUTMPPG  ON TBAUT.AUT_ID = AUTMPPG.AUT_ID
        INNER JOIN KOA_TB_MBR AS TBMBR  ON TBMBR.MBR_ID = AUTMPPG.MBR_ID
WHERE 1=1

    AND AUTMPPG.MBR_ID = #{mbrId}


    AND AUT_NM = #{autNm}

