/* com.kt.openapi.web.apiDeploy.dao.ApiDeployDAO.apiVerNoUpdate */              
UPDATE KOA_TB_API_DEF
  SET API_VER_NO = #{setApiVerNo}
WHERE 
  API_NO = #{apiNo}
